      "question": "📜 **खालील कविता काळजीपूर्वक वाचा व विचारलेल्या प्रश्नाचे योग्य उत्तर निवडा:**\n\nमातीच्या कुशीत झोपले बीज,\nउद्या उगवेल तृणांकुर सतेज!\nकवेत घेऊनी नभाची निळाई,\nगातील गाणी पाखरे सुहास्य!\n\nजरी संकटांचे डोंगर कोसळले,\nतरी ध्येयवेड्याने डगमगू नये;\nपंखात बळ घेउनी विहंग उडती,\nवादळातही ते मागे न हटती!\n\nमायभूमी ही माझी प्रत्यक्ष जननी,\nअमृताची धार तिच्या पावन चरणी;\nसेवा तिची करणे हाच माझा धर्म,\nदेशकार्यात वाहावे अहोरात्र कर्म!\n\n**प्रश्न ११.** 'मातीच्या कुशीत झोपले बीज, उद्या उगवेल तृणांकुर सतेज.' यात कोणता विचार मांडला आहे?",
